-- table: event_sports
CREATE TABLE IF NOT EXISTS public.event_sports (
    event_id character(26) NOT NULL,
    sports_event_id text,
    sports_event_slug text,
    sports_parent_event_id bigint,
    sports_game_id bigint,
    sports_event_date date,
    sports_start_time timestamp with time zone,
    sports_series_slug text,
    sports_series_id text,
    sports_series_recurrence text,
    sports_series_color text,
    sports_sport_slug text,
    sports_event_week integer,
    sports_score text,
    sports_period text,
    sports_elapsed text,
    sports_live boolean,
    sports_ended boolean,
    sports_tags jsonb,
    sports_teams jsonb,
    sports_team_logo_urls jsonb,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    sports_league_label text,
    sports_league_slug text,
    sports_source_provider text,
    sports_source_event_id text,
    sports_source_game_id text,
    sports_source_league_id text,
    sports_source_league_label text,
    sports_source_match_confidence numeric(6,4),
    sports_source_payload jsonb,
    sports_source_selected_at timestamp with time zone,
    sports_segment_scores jsonb,
    CONSTRAINT event_sports_source_match_confidence_range CHECK (((sports_source_match_confidence IS NULL) OR ((sports_source_match_confidence >= (0)::numeric) AND (sports_source_match_confidence <= (1)::numeric))))
);

-- table: market_sports
CREATE TABLE IF NOT EXISTS public.market_sports (
    condition_id text NOT NULL,
    event_id character(26),
    sports_market_type text,
    sports_line numeric(20,8),
    sports_group_item_title text,
    sports_group_item_threshold text,
    sports_game_start_time timestamp with time zone,
    sports_event_id bigint,
    sports_parent_event_id bigint,
    sports_game_id bigint,
    sports_event_date date,
    sports_start_time timestamp with time zone,
    sports_series_color text,
    sports_event_slug text,
    sports_teams jsonb,
    sports_team_logo_urls jsonb,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    sports_source_provider text,
    sports_source_event_id text,
    sports_source_game_id text,
    sports_source_league_id text,
    sports_source_league_label text,
    sports_source_market_id text,
    sports_source_match_confidence numeric(6,4),
    sports_source_payload jsonb,
    CONSTRAINT market_sports_source_match_confidence_range CHECK (((sports_source_match_confidence IS NULL) OR ((sports_source_match_confidence >= (0)::numeric) AND (sports_source_match_confidence <= (1)::numeric))))
);

-- table: series_social_trackers
CREATE TABLE IF NOT EXISTS public.series_social_trackers (
    id smallint NOT NULL,
    series_slug text NOT NULL,
    platform text DEFAULT 'X'::text NOT NULL,
    handle text NOT NULL,
    display_name text NOT NULL,
    is_verified boolean DEFAULT false NOT NULL,
    bio text,
    is_active boolean DEFAULT true NOT NULL,
    priority smallint DEFAULT 0 NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT series_social_trackers_platform_check CHECK ((platform = ANY (ARRAY['X'::text, 'TRUTH_SOCIAL'::text]))),
    CONSTRAINT series_social_trackers_priority_check CHECK ((priority >= 0))
);

-- table: sports_menu_items
CREATE TABLE IF NOT EXISTS public.sports_menu_items (
    id text NOT NULL,
    item_type text NOT NULL,
    label text,
    href text,
    icon_url text,
    parent_id text,
    menu_slug text,
    h1_title text,
    mapped_tags jsonb DEFAULT '[]'::jsonb NOT NULL,
    url_aliases jsonb DEFAULT '[]'::jsonb NOT NULL,
    games_enabled boolean DEFAULT true NOT NULL,
    props_enabled boolean DEFAULT true NOT NULL,
    sort_order integer DEFAULT 0 NOT NULL,
    enabled boolean DEFAULT true NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    sidebar_category boolean DEFAULT false NOT NULL,
    sidebar_enabled boolean DEFAULT false NOT NULL,
    sidebar_featured boolean DEFAULT false NOT NULL,
    sidebar_sort_order integer DEFAULT 0 NOT NULL,
    CONSTRAINT sports_menu_items_item_type_check CHECK ((item_type = ANY (ARRAY['link'::text, 'group'::text, 'header'::text, 'divider'::text]))),
    CONSTRAINT sports_menu_items_mapped_tags_is_array CHECK ((jsonb_typeof(mapped_tags) = 'array'::text)),
    CONSTRAINT sports_menu_items_url_aliases_is_array CHECK ((jsonb_typeof(url_aliases) = 'array'::text))
);

